def _cargar_etapa(nombre: str) -> types.ModuleType:
    modulo = types.ModuleType(f"fase1_{nombre}")
    modulo.__file__ = f"<etapa_embebida:{nombre}>"
    sys.modules[modulo.__name__] = modulo
    exec(compile(_STAGE_SOURCES[nombre], modulo.__file__, "exec"), modulo.__dict__)
    return modulo


def _leer_tabla(ruta: Path, hoja: str | int | None = None) -> pd.DataFrame:
    if ruta.suffix.casefold() in {".xlsx", ".xls", ".xlsm"}:
        return pd.read_excel(ruta, sheet_name=0 if hoja is None else hoja, dtype=str).fillna("")
    return pd.read_csv(ruta, dtype=str, encoding="utf-8-sig", keep_default_na=False, low_memory=False)


def _guardar_limpieza(modulo, entrada: Path, carpeta: Path) -> tuple[Path, dict[str, int]]:
    carpeta.mkdir(parents=True, exist_ok=True)
    df = modulo.leer_archivo(entrada, modulo.HOJA_ENTRADA)
    depurado, auditoria, actores_recortados, fragmentos_excluidos = modulo.depurar_notas_de_actores(df)
    limpio, cambios = modulo.limpiar_dataframe(depurado)
    if len(limpio) + fragmentos_excluidos != len(df):
        raise RuntimeError("La conciliacion de registros de la limpieza fallo.")

    csv_salida = carpeta / "FASE1_LIMPIEZA_COMPLETA.csv"
    xlsx_salida = carpeta / "FASE1_LIMPIEZA_COMPLETA.xlsx"
    auditoria_salida = carpeta / "FASE1_AUDITORIA_LIMPIEZA_ACTORES.csv"
    limpio.to_csv(csv_salida, index=False, encoding="utf-8-sig")
    limpio.to_excel(xlsx_salida, sheet_name=modulo.HOJA_SALIDA, index=False)
    if auditoria.empty:
        pd.DataFrame(columns=["accion_limpieza", "actor_resultante", *df.columns]).to_csv(
            auditoria_salida, index=False, encoding="utf-8-sig"
        )
    else:
        auditoria.to_csv(auditoria_salida, index=False, encoding="utf-8-sig")

    metricas = {
        "registros_antes_limpieza": int(len(df)),
        "registros_despues_limpieza": int(len(limpio)),
        "actores_recortados_nota_editorial": int(actores_recortados),
        "filas_narrativas_excluidas": int(fragmentos_excluidos),
        **{f"valores_modificados_{k}": int(v) for k, v in cambios.items()},
    }
    return csv_salida, metricas


def _crear_decisiones(ruta: Path) -> Path:
    ruta.parent.mkdir(parents=True, exist_ok=True)
    pd.DataFrame(_DECISIONES_CASOS).to_csv(ruta, index=False, encoding="utf-8-sig")
    return ruta


def _serie_resumen_scraping(entrada: Path, resumen_externo: Path | None) -> pd.DataFrame:
    if resumen_externo is not None:
        return _leer_tabla(resumen_externo)
    if entrada.suffix.casefold() in {".xlsx", ".xls", ".xlsm"}:
        try:
            return pd.read_excel(entrada, sheet_name="Resumen por reporte")
        except ValueError:
            return pd.DataFrame()
    candidato = entrada.parent / "fase1_resumen_reportes_2021_2025_solo_hechos.csv"
    return _leer_tabla(candidato) if candidato.exists() else pd.DataFrame()


def _numero(tabla: pd.DataFrame, columna: str) -> int:
    if tabla.empty or columna not in tabla.columns:
        return 0
    return int(pd.to_numeric(tabla[columna], errors="coerce").fillna(0).sum())


def _relaciones_unicas(base: pd.DataFrame) -> pd.DataFrame:
    claves = ["periodo_reporte", "id_caso", "Id_actor"]
    faltantes = [c for c in claves if c not in base.columns]
    if faltantes:
        raise ValueError(f"Faltan columnas para las relaciones unicas: {faltantes}")
    salida = base.copy()
    salida["_orden"] = range(len(salida))
    if "tipo_actor" in salida.columns:
        tipos = (
            salida.groupby(claves, sort=False, dropna=False)["tipo_actor"]
            .agg(lambda s: " | ".join(dict.fromkeys(x for x in s.astype(str) if x)))
            .rename("tipo_actor_consolidado")
            .reset_index()
        )
    else:
        tipos = None
    salida = salida.sort_values("_orden", kind="stable").drop_duplicates(claves, keep="first")
    salida = salida.drop(columns="_orden")
    if tipos is not None:
        salida = salida.drop(columns=["tipo_actor"]).merge(tipos, on=claves, how="left", validate="one_to_one")
        salida = salida.rename(columns={"tipo_actor_consolidado": "tipo_actor"})
    return salida


def _agregar(filas: list[dict[str, object]], subseccion: str, indicador: str, valor: object, fuente: str) -> None:
    filas.append({"subseccion": subseccion, "indicador": indicador, "valor": valor, "fuente": fuente})


def _escape_latex(valor: object) -> str:
    texto = str(valor)
    reemplazos = {"\\": r"\textbackslash{}", "&": r"\&", "%": r"\%", "$": r"\$", "#": r"\#", "_": r"\_", "{": r"\{", "}": r"\}"}
    for original, nuevo in reemplazos.items():
        texto = texto.replace(original, nuevo)
    return texto


def _exportar_latex(resumen: pd.DataFrame, ruta: Path) -> None:
    lineas = [
        "% Generado automaticamente por pipeline_fase1_unificado.py",
        "% Contiene solo indicadores numericos; la interpretacion se redacta por separado.",
        "",
    ]
    for subseccion, grupo in resumen.groupby("subseccion", sort=False):
        lineas.extend([
            rf"\subsection{{{_escape_latex(subseccion)}}}",
            "",
            r"\begin{table}[htbp]",
            r"    \centering",
            rf"    \caption{{Indicadores de {_escape_latex(subseccion.lower())}}}",
            r"    \small",
            r"    \begin{tabular}{lr}",
            r"    \toprule",
            r"    \textbf{Indicador} & \textbf{Valor} \\",
            r"    \midrule",
        ])
        for fila in grupo.itertuples(index=False):
            valor = fila.valor
            if isinstance(valor, float) and valor.is_integer():
                valor = int(valor)
            if isinstance(valor, int):
                valor = f"{valor:,}".replace(",", r"\,")
            lineas.append(rf"    {_escape_latex(fila.indicador)} & {valor} \\")
        lineas.extend([
            r"    \bottomrule",
            r"    \end{tabular}",
            r"    \par\smallskip",
            r"    {\footnotesize\textit{Fuente: elaboración propia.}}",
            r"\end{table}",
            "",
        ])
    ruta.write_text("\n".join(lineas), encoding="utf-8")


def _construir_resumen(
    entrada_scraping: Path,
    resumen_scraping: pd.DataFrame,
    metricas_limpieza: dict[str, int],
    filtro_dir: Path,
    maestro_dir: Path,
    actores_dir: Path,
    casos_dir: Path,
    base_final: pd.DataFrame,
    relaciones: pd.DataFrame,
) -> pd.DataFrame:
    datos_extraidos = _leer_tabla(entrada_scraping, "Datos extraídos" if entrada_scraping.suffix.casefold().startswith(".xls") else None)
    filtro = json.loads((filtro_dir / "FASE1_RESUMEN_FILTRO_MINERIA_2021_2025.json").read_text(encoding="utf-8"))
    maestro = _leer_tabla(maestro_dir / "MAESTRO_ACTORES_CORREGIDO_3_COLUMNAS.csv")
    resumen_actores = _leer_tabla(actores_dir / "FASE1_RESUMEN_ASIGNACION_IDS_ACTORES.csv")
    resumen_casos = _leer_tabla(casos_dir / "RESUMEN_ASIGNACION_IDS_CASOS.csv")
    valor_actores = dict(zip(resumen_actores["indicador"], pd.to_numeric(resumen_actores["valor"], errors="coerce").fillna(0).astype(int)))
    valor_casos = dict(zip(resumen_casos["indicador"], pd.to_numeric(resumen_casos["valor"], errors="coerce").fillna(0).astype(int)))
    filas: list[dict[str, object]] = []

    s1 = "Cobertura documental y extracción de los reportes mensuales"
    _agregar(filas, s1, "Reportes procesados", int(len(resumen_scraping)) if not resumen_scraping.empty else int(datos_extraidos["reporte"].nunique()), "resumen del scraping")
    _agregar(filas, s1, "Periodos mensuales cubiertos", int(datos_extraidos["periodo_reporte"].nunique()), "base extraída")
    _agregar(filas, s1, "Páginas PDF procesadas", _numero(resumen_scraping, "paginas_pdf"), "resumen del scraping")
    _agregar(filas, s1, "Casos-periodo detectados en los PDF", _numero(resumen_scraping, "casos_detectados_pdf"), "resumen del scraping")
    registros_actor_extraidos = _numero(resumen_scraping, "registros_actor_detectados")
    if registros_actor_extraidos == 0 and "registros_actor_detectados" not in resumen_scraping.columns:
        raise ValueError(
            "El resumen del scraping no contiene 'registros_actor_detectados'. "
            "Reejecute el scraping con este pipeline corregido para obtener el conteo previo al filtro de hechos."
        )
    _agregar(filas, s1, "Registros actor–conflicto extraídos", registros_actor_extraidos, "resumen del scraping antes del filtro de hechos")
    _agregar(filas, s1, "Actores originales distintos en la extracción", int(datos_extraidos["actor"].nunique()), "base extraída")
    _agregar(filas, s1, "Inconsistencias registradas", _numero(resumen_scraping, "inconsistencias_registradas"), "resumen del scraping")

    s2 = "Selección de casos con hechos reportados en el periodo"
    _agregar(filas, s2, "Casos-periodo detectados antes del filtro", _numero(resumen_scraping, "casos_detectados_pdf"), "resumen del scraping")
    _agregar(filas, s2, "Casos-periodo con hechos", _numero(resumen_scraping, "casos_con_hechos"), "resumen del scraping")
    _agregar(filas, s2, "Casos-periodo sin hechos excluidos", _numero(resumen_scraping, "casos_sin_hechos"), "resumen del scraping")
    _agregar(filas, s2, "Casos-periodo conservados", int(datos_extraidos[["periodo_reporte", "nombre_caso"]].drop_duplicates().shape[0]), "base solo hechos")
    _agregar(filas, s2, "Registros actor–conflicto conservados", int(len(datos_extraidos)), "base solo hechos")

    s3 = "Limpieza y selección de conflictos vinculados con la actividad minera"
    for indicador, clave in [
        ("Registros antes de la limpieza", "registros_antes_limpieza"),
        ("Registros después de la limpieza", "registros_despues_limpieza"),
        ("Actores recortados por nota editorial", "actores_recortados_nota_editorial"),
        ("Filas narrativas excluidas", "filas_narrativas_excluidas"),
    ]:
        _agregar(filas, s3, indicador, metricas_limpieza[clave], "auditoría de limpieza")
    _agregar(filas, s3, "Registros socioambientales examinados", filtro["filas_socioambientales"], "resumen del filtro minero")
    _agregar(filas, s3, "Conflictos socioambientales distintos examinados", filtro["casos_socioambientales_unicos_por_nombre"], "resumen del filtro minero")
    _agregar(filas, s3, "Conflictos mineros distintos seleccionados", filtro["casos_mineros_unicos_por_nombre"], "resumen del filtro minero")
    _agregar(filas, s3, "Registros actor–conflicto mineros", filtro["filas_mineras_salida"], "resumen del filtro minero")
    _agregar(filas, s3, "Actores originales distintos en la base minera", filtro["actores_originales_salida"], "resumen del filtro minero")
    _agregar(filas, s3, "Casos pendientes de revisión minera", filtro["casos_para_revisar"], "resumen del filtro minero")

    s4 = "Normalización e identificación longitudinal de actores y conflictos"
    _agregar(filas, s4, "Nombres reales únicos de actores", int(maestro["NOMBRE REAL"].nunique()), "maestro de actores")
    _agregar(filas, s4, "Correspondencias nombre real–actor normalizado", int(len(maestro)), "maestro de actores")
    _agregar(filas, s4, "Actores normalizados con ID", int(maestro["ID"].nunique()), "maestro de actores")
    _agregar(filas, s4, "Nombres compuestos únicos separados", valor_actores["Nombres compuestos únicos en el maestro"], "resumen de IDs de actores")
    _agregar(filas, s4, "Filas después de expandir nombres compuestos", valor_actores["Filas de salida después de expandir compuestos"], "resumen de IDs de actores")
    _agregar(filas, s4, "Actores sin ID", valor_actores["Actores sin ID"], "resumen de IDs de actores")
    _agregar(filas, s4, "Nombres originales de conflicto", valor_casos["Nombres originales únicos"], "resumen de IDs de casos")
    _agregar(filas, s4, "Variantes comparables de conflicto", valor_casos["Variantes comparables únicas"], "resumen de IDs de casos")
    _agregar(filas, s4, "Vínculos automáticos de casos", valor_casos["Vínculos automáticos"], "resumen de IDs de casos")
    _agregar(filas, s4, "Decisiones manuales aplicadas", valor_casos["Decisiones manuales aplicadas"], "resumen de IDs de casos")
    _agregar(filas, s4, "Pares pendientes de revisión", valor_casos["Pares pendientes de revisión"], "resumen de IDs de casos")
    _agregar(filas, s4, "Identificadores longitudinales de conflicto", int(base_final["id_caso"].nunique()), "base final")
    _agregar(filas, s4, "Filas sin id_caso", valor_casos["Filas finales sin id_caso"], "resumen de IDs de casos")

    s5 = "Depuración, trazabilidad y verificación de consistencia"
    claves = ["periodo_reporte", "id_caso", "Id_actor"]
    exactos = int(base_final.duplicated().sum())
    sin_exactos = base_final.drop_duplicates()
    repetidos_clave = int(sin_exactos.duplicated(claves).sum())
    _agregar(filas, s5, "Registros de la base consolidada", int(len(base_final)), "base final")
    _agregar(filas, s5, "Duplicados exactos", exactos, "base final")
    _agregar(filas, s5, "Registros sin duplicados exactos", int(len(sin_exactos)), "base final")
    _agregar(filas, s5, "Ocurrencias adicionales de la clave periodo–caso–actor", repetidos_clave, "base final")
    _agregar(filas, s5, "Relaciones mensuales únicas", int(len(relaciones)), "tabla de relaciones")
    _agregar(filas, s5, "Actores normalizados", int(base_final["Id_actor"].nunique()), "base final")
    _agregar(filas, s5, "Conflictos longitudinales", int(base_final["id_caso"].nunique()), "base final")
    _agregar(filas, s5, "Periodos mensuales", int(base_final["periodo_reporte"].nunique()), "base final")
    _agregar(filas, s5, "Claves repetidas en la tabla de relaciones", int(relaciones.duplicated(claves).sum()), "tabla de relaciones")
    _agregar(filas, s5, "IDs actor vacíos", int(base_final["Id_actor"].astype(str).str.strip().eq("").sum()), "base final")
    _agregar(filas, s5, "IDs caso vacíos", int(base_final["id_caso"].astype(str).str.strip().eq("").sum()), "base final")
    return pd.DataFrame(filas)


def ejecutar(args: argparse.Namespace) -> None:
    salida = args.out_dir.resolve()
    salida.mkdir(parents=True, exist_ok=True)
    modulos = {nombre: _cargar_etapa(nombre) for nombre in _STAGE_SOURCES}

    if args.entrada_scraping:
        entrada_scraping = args.entrada_scraping.resolve()
        if not entrada_scraping.exists():
            raise FileNotFoundError(entrada_scraping)
    else:
        if args.pdf_dir is None:
            raise ValueError("Indique --pdf-dir o --entrada-scraping.")
        carpeta_scraping = salida / "01_scraping"
        ns = argparse.Namespace(
            pdf_dir=str(args.pdf_dir.resolve()), out_dir=str(carpeta_scraping),
            report_from=203, report_to=262, force=args.force, combine=True,
            no_xlsx=False, solo_con_hechos=True,
        )
        codigo = modulos["scraper"].run(ns)
        if codigo:
            raise RuntimeError(f"El scraping terminó con código {codigo}.")
        entrada_scraping = carpeta_scraping / "FASE1_scraping_conflictos_sociales_2021_2025_solo_hechos.xlsx"

    resumen_scraping = _serie_resumen_scraping(entrada_scraping, args.resumen_scraping)
    limpio_csv, metricas_limpieza = _guardar_limpieza(modulos["limpieza"], entrada_scraping, salida / "02_limpieza")

    filtro_dir = salida / "03_filtro_mineria"
    modulos["filtro"].ejecutar(limpio_csv, filtro_dir)
    base_minera = filtro_dir / "FASE1_SOCIOAMBIENTALES_MINERIA_2021_2025.csv"

    maestro_dir = salida / "04_normalizacion_actores"
    modulos["maestro_actores"].ejecutar(base_minera, "actor", None, maestro_dir, True)
    maestro_csv = maestro_dir / "MAESTRO_ACTORES_CORREGIDO_3_COLUMNAS.csv"

    actores_dir = salida / "05_ids_actores"
    modulos["incorporar_actores"].ejecutar(base_minera, maestro_csv, actores_dir, None, False)
    base_actores = actores_dir / "FASE1_MINERIA_CON_IDS_ACTORES.csv"

    decisiones = args.decisiones.resolve() if args.decisiones else _crear_decisiones(salida / "06_ids_casos" / "DECISIONES_CASOS_REVISADAS.csv")
    casos_dir = salida / "06_ids_casos"
    modulos["casos"].ejecutar(base_actores, casos_dir, decisiones, None, 0.85)
    final_csv = casos_dir / "FASE1_MINERIA_CON_IDS_ACTORES_Y_CASOS.csv"
    base_final = _leer_tabla(final_csv)

    relaciones = _relaciones_unicas(base_final)
    relaciones_csv = salida / "FASE1_RELACIONES_MENSUALES_UNICAS.csv"
    relaciones.to_csv(relaciones_csv, index=False, encoding="utf-8-sig")

    resumen = _construir_resumen(
        entrada_scraping, resumen_scraping, metricas_limpieza, filtro_dir,
        maestro_dir, actores_dir, casos_dir, base_final, relaciones,
    )
    resumen_csv = salida / "RESUMEN_RESULTADOS_FASE1.csv"
    resumen.to_csv(resumen_csv, index=False, encoding="utf-8-sig")

    mensual = (
        base_final.groupby("periodo_reporte", sort=True)
        .agg(registros=("Id_actor", "size"), casos=("id_caso", "nunique"), actores=("Id_actor", "nunique"))
        .reset_index()
    )
    mensual.to_csv(salida / "RESUMEN_MENSUAL_CASOS_ACTORES_FASE1.csv", index=False, encoding="utf-8-sig")
    _exportar_latex(resumen, salida / "RESULTADOS_NUMERICOS_FASE1.tex")

    copia_final_csv = salida / "FASE1_MINERIA_CON_IDS_ACTORES_Y_CASOS.csv"
    copia_final_excel = salida / "FASE1_MINERIA_CON_IDS_ACTORES_Y_CASOS.xlsx"
    base_final.to_csv(copia_final_csv, index=False, encoding="utf-8-sig")
    base_final.to_excel(
        copia_final_excel,
        sheet_name="Base final fase 1",
        index=False,
    )

    manifiesto = {
        "base_final_csv": str(copia_final_csv),
        "base_final_excel": str(copia_final_excel),
        "filas_base_final": int(len(base_final)),
        "actores": int(base_final["Id_actor"].nunique()),
        "conflictos": int(base_final["id_caso"].nunique()),
        "periodos": int(base_final["periodo_reporte"].nunique()),
        "relaciones_mensuales_unicas": int(len(relaciones)),
        "resumen_resultados": str(resumen_csv),
    }
    (salida / "MANIFIESTO_FASE1.json").write_text(json.dumps(manifiesto, ensure_ascii=False, indent=2), encoding="utf-8")
    print("\nPIPELINE FASE 1 FINALIZADO")
    print(json.dumps(manifiesto, ensure_ascii=False, indent=2))


def construir_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Ejecuta toda la Fase 1 y genera los conteos para resultados.")
    parser.add_argument("--pdf-dir", type=Path, default=Path("reportes_pdf"), help="Carpeta con los reportes PDF 203-262.")
    parser.add_argument("--entrada-scraping", type=Path, default=None, help="Excel/CSV consolidado para reanudar sin procesar PDF.")
    parser.add_argument("--resumen-scraping", type=Path, default=None, help="CSV opcional de resumen por reporte cuando la entrada es CSV.")
    parser.add_argument("--out-dir", type=Path, default=Path("resultados_fase1_unificado"))
    parser.add_argument("--decisiones", type=Path, default=None, help="CSV alternativo con decisiones MISMO/DIFERENTE.")
    parser.add_argument("--force", action="store_true", help="Reprocesa checkpoints de PDF existentes.")
    return parser


if __name__ == "__main__":
    ejecutar(construir_parser().parse_args())
